import signal
import errno
import os
from taf.ul.ettf.logger import custom_logger
from taf.ul.ettf.utils.paths import unique_name
from .exception import LibraryError
from . import exception_causes


logger = custom_logger('Timeout')


class TimeoutError(LibraryError):
    def __init__(self, msg):
        super(TimeoutError, self).__init__(exception_causes.TIMEOUT, msg)


def raise_timeout_exception(error_message):
    raise TimeoutError(error_message)


def default_timeout_error(error_message=os.strerror(errno.ETIME)):
    return lambda signum, frame: raise_timeout_exception(error_message)


def _default_timer_name():
    return 'T_{}'.format(unique_name)


class Timeout(object):
    is_set = False

    def __init__(self, timeout=10, timer_name=_default_timer_name(), timeout_handler=default_timeout_error()):
        assert timeout > 0, 'Timeout value should be greater than 0'
        self.timer_name = timer_name
        self.timeout = timeout
        self.timeout_handler = timeout_handler

    def __enter__(self):
        self._start_timer()

    def __exit__(self, *args, **kwargs):
        self._stop_timer()

    def __call__(self, func):

        def _wrapper(*args, **kwargs):
            try:
                self._start_timer()
                result = func(*args, **kwargs)
            finally:
                self._stop_timer()
            return result

        return _wrapper

    def _start_timer(self):
        self._check_is_timeout_set()
        logger.debug('Start timer {}'.format(self.timer_name))
        Timeout.is_set = True
        signal.signal(signal.SIGALRM, self.timeout_handler)
        signal.alarm(self.timeout)

    def _stop_timer(self):
        signal.alarm(0)
        Timeout.is_set = False
        logger.debug('Stop timer {}'.format(self.timer_name))

    @staticmethod
    def _check_is_timeout_set():
        if Timeout.is_set:
            raise TimeoutError("Timeout is already set!")
